-- Version history: add the 2.0.0 entry (the rewrite) once. Idempotent: skipped if a 2.0.0 entry exists.
INSERT INTO "site_config" ("key", "value")
VALUES ('changelog', $cl$[{"date":"2026-10-07T12:00:00.000Z","title":"The big rewrite","version":"2.0.0","description":"The site has been rebuilt from the ground up. Pages load fast, every record is computed on the server, and a lot is new.\n\n**Records**\n- 139 records in 17 sections, including whole new families: **Luck and Regret** (unluckiest loss, luckiest win, should-have-won, heartbreak playoff losses), **Projections**, **NFL Byes and Inactives** (starting a player on a bye or who was out), **Pickups and Trades**, **Players**, **Draft**, **Rivalries**, **Seeds and Finishes** and **Droughts and Dynasties**.\n- Median-split records: won the head-to-head but lost to the median, and the reverse.\n- Filter by time (all, regular season, playoffs, toilet bowl, postseason), median included or excluded, season, franchise and opponent, one row per season, and page through the results. Every filter is in the URL, so a copied link shows the same view.\n- Ties share a rank, every record has a description, and lineup IQ now uses the exact best possible lineup for each week.\n\n**Franchises and trophies**\n- Franchise pages with a head-to-head heatmap, a profile and a trophy cabinet, plus a Trophies page with champions, podiums, last places and clubs.\n\n**Seasons**\n- Standings with a week picker, live matchups with full lineups, teams and rosters, transactions with filters, the draft, and future picks for the dynasty league.\n- 2020 and 2021 now have real lineups, transactions, drafts and playoff brackets from ESPN. 2020's two-week playoff games count as one game, left out of single-week and lineup records.\n- Final placements come from the real brackets.\n\n**Everything else**\n- Works on phones and in dark mode.\n- A private admin area for the commissioner: invite-only accounts, score and placement corrections with a recorded reason (they survive data refreshes), thresholds, record settings, an unmatched-player queue, job controls and an audit log.\n- Data refreshes itself: rosters and transactions daily, scores every few minutes on game days, and the week is finalized on Tuesday.\n\n**Heads up:** some numbers differ from the old site on purpose (idle playoff teams no longer play fake games, ESPN playoff weeks are real bracket games, and dynasty 2023 is scored as played). The parity report in the repository lists every difference."}]$cl$::jsonb)
ON CONFLICT ("key") DO UPDATE
  SET "value" = EXCLUDED."value" || "site_config"."value", "updated_at" = now()
  WHERE NOT ("site_config"."value" @> '[{"version": "2.0.0"}]'::jsonb);
